<script lang="ts">
							import SectionComponent from '$lib/section/SectionComponent.svelte';
							import copy from "copy-to-clipboard"; 
							import { onMount } from "svelte";
							import PrevNextSection from '$lib/prevNext/PrevNextSection.svelte';

							interface ComponentProps {
								setVisible: (id: string, v: boolean) => void;
							}
							let { setVisible }: ComponentProps = $props();
							
							const visibleById = $state<Record<string, boolean>>({});

							/**
               * This function will go through all the 'pre' elements
               * on the page and add a copy button to them.
               * Thanks to: https://slavbasharov.com/blog/adding-click-to-copy-code-markdown-blog
               */
              onMount(() => {
                  const codeBlocks = document.querySelectorAll("pre");
                  codeBlocks.forEach((block) => {
                      const copyPrompt = document.createElement("div");
                      copyPrompt.className = "copy-prompt";
                      const copyPromptText = document.createElement("p");
                      copyPromptText.innerHTML = "👆 Click to copy";
                      copyPromptText.className = 'copy-prompt-p';
                      const copyIcon = document.createElement("img");
                      copyIcon.src = "/icons/copy-icon.svg";
                      copyIcon.className = "copy-prompt-img";
                      copyPrompt.appendChild(copyIcon);
                      copyPrompt.appendChild(copyPromptText);
                      block.appendChild(copyPrompt);
											block.querySelector('.copy-prompt > p')?.addEventListener('click', () => {
												if (block.querySelector('code')?.textContent !== null && block.querySelector('code')?.textContent !== undefined) {
													copy(block.querySelector('code')!.textContent!);
												}
												if (block.querySelector('.copy-prompt > p')?.innerHTML !== null && block.querySelector('.copy-prompt > p')?.innerHTML !== undefined) {
													block.querySelector('.copy-prompt > p')!.innerHTML = 'Copied!';
													setTimeout(() => {
														block.querySelector('.copy-prompt > p')!.innerHTML = '👆 Click to copy';
													}, 1000);
												}
											});
                  });
              });
		let prevLink= '/Documentation/Overview/Running_Example';
    let nextLink= '/Documentation/Creating_the_Metamodel/Language_Structure';
    
    import Note from "$lib/notes/Note.svelte";
</script>

<PrevNextSection {prevLink} {nextLink} />



<SectionComponent tag="h1" 
  id="creating-the-metamodel-1"
  bind:intersecting={visibleById["creating-the-metamodel-1"]}
  onIntersectChange={(visible) => setVisible("creating-the-metamodel-1", visible)}
>Creating the Metamodel</SectionComponent>
<p>The metamodel, or abstract syntax tree (AST), of the language is described in files with the extension <code>.ast</code>.
All files with this extension in the <a
  href="/Documentation/Overview/Getting_Started#creating-a-project-2"
><em>defs</em> folder</a> (i.e. the folder where you keep your definition files)
are combined into one AST definition.</p>
<SectionComponent tag="h2" 
  id="every-language-has-a-name-2"
  bind:intersecting={visibleById["every-language-has-a-name-2"]}
  onIntersectChange={(visible) => setVisible("every-language-has-a-name-2", visible)}
>Every Language has a Name</SectionComponent>
<p>Every AST file must start with the declaration of the name of your language. This name is used
to form the names of several generated TypeScript classes.</p>
<pre class="language-freon"><code class="language-freon">// Insurance/src/defs/language-main.ast#L1-L2

language InsuranceModel
</code></pre>
<p>The Freon language structure consists of a single <a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#model-2"
>Model</a> and the following elements: </p>
<ul>
<li><a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#model-unit-3"
>Model Units</a>,</li>
<li><a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#concept-4"
>Concepts</a>,</li>
<li><a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#expression-concept-5"
>Expression Concepts</a>,</li>
<li><a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#binary-expression-concept-6"
>Binary Expression Concepts</a>,</li>
<li><a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#limited-concept-7"
>Limited Concepts</a></li>
<li><a
  href="/Documentation/Creating_the_Metamodel/Language_Structure#interface-8"
>Interfaces</a></li>
</ul>
<p>Each of these will be explained in the next section.</p>


<PrevNextSection {prevLink} {nextLink} />